/* @lc app=leetcode id=3756 lang=kotlin */ class Solution { fun sumAndMultiply(s: String, queries: Array<IntArray>): IntArray = 1_000_000_007L.let { M -> s.length.let { n -> IntArray(n + 1).also { c -> s.indices.forEach { c[it + 1] = c[it] + (if (s[it] != '0') 1 else 0) } }.let { cnt -> s.runningFold(0L) { a, ch -> if (ch != '0') (a * 10 + (ch - '0')) % M else a }.let { xp -> s.runningFold(0L) { a, ch -> a + (ch - '0') }.let { sm -> generateSequence(1L) { it * 10 % M }.take(n + 1).toList().let { pw -> queries.map { (l, r) -> (((xp[r + 1] - xp[l] * pw[cnt[r + 1] - cnt[l]]) % M + M) % M * ((sm[r + 1] - sm[l]) % M) % M).toInt() }.toIntArray() } } } } } } }